response.experiment:
results = []
for f in [-10, -2, -1, 0, 1, 10]:
    r = call("observe", {"force": f, "duration": 1.0})
    if r["status"] == "ok":
        results.append({"force": f, "duration": 1.0, "position": r["result"]["position"], "velocity": r["result"]["velocity"], "evidence_id": r["evidence_id"]})
    else:
        results.append({"force": f, "duration": 1.0, "error_status": r["status"]})
for d in [0.25, 0.5, 2.0, 4.0]:
    r = call("observe", {"force": 2.0, "duration": d})
    if r["status"] == "ok":
        results.append({"force": 2.0, "duration": d, "position": r["result"]["position"], "velocity": r["result"]["velocity"], "evidence_id": r["evidence_id"]})
    else:
        results.append({"force": 2.0, "duration": d, "error_status": r["status"]})
emit(results)

